/* Generated by the production build. Old versions remain active until all game tabs close. */
const CACHE_NAME = __CACHE_NAME__;
const PRECACHE_URLS = __PRECACHE_URLS__;
const GAME_URLS = new Set(PRECACHE_URLS);

self.addEventListener('install', event => {
  event.waitUntil((async () => {
    const cache = await caches.open(CACHE_NAME);
    // addAll is atomic: an incomplete game is never advertised as saved.
    await cache.addAll(PRECACHE_URLS.map(url => new Request(url, { cache: 'reload' })));
  })());
  // Deliberately no skipWaiting: updates must not change assets during a run.
});

self.addEventListener('activate', event => {
  event.waitUntil((async () => {
    const keys = await caches.keys();
    await Promise.all(keys.filter(key => key.startsWith('lakhey-run-game-') && key !== CACHE_NAME)
      .map(key => caches.delete(key)));
  })());
  // No clients.claim: first-time pages continue loading their original build.
});

self.addEventListener('fetch', event => {
  const request = event.request;
  const url = new URL(request.url);
  if (request.method !== 'GET' || url.origin !== self.location.origin) return;
  const gameNavigation = request.mode === 'navigate' && (url.pathname === '/' || url.pathname === '/index.html');
  // Viewer pages and unrelated resources are intentionally outside this game snapshot.
  if (!gameNavigation && !GAME_URLS.has(url.pathname)) return;
  event.respondWith((async () => {
    const cache = await caches.open(CACHE_NAME);
    const key = gameNavigation ? '/index.html' : url.pathname;
    const saved = await cache.match(key);
    if (saved) return saved;
    try { return await fetch(request); }
    catch {
      if (!gameNavigation) return Response.error();
      return new Response(`<!doctype html><html lang="en"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Lakhey Run — reconnect</title><body style="background:#0b0e14;color:#e5e7eb;font:18px system-ui;padding:32px"><h1>Reconnect to run</h1><p>The saved game is unavailable. Connect to the internet and reload.</p><button onclick="location.reload()" style="padding:14px">Try again</button></body></html>`, { status: 503, headers: { 'Content-Type': 'text/html; charset=utf-8' } });
    }
  })());
});
